function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value of nums is an integer from 0 to 100.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 entries.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 2) return 'Each query is a pair [time, index].';
    if (!Number.isInteger(q[0]) || q[0] < 0 || q[0] > 100000) return 'Each time is an integer from 0 to 100000.';
    if (!Number.isInteger(q[1]) || q[1] < 0 || q[1] >= nums.length) return 'Each index is between 0 and nums.length - 1.';
  }
  return null;
}

