function elementInNums(nums, queries) {
  const n = nums.length;
  const answer = [];
  for (const [time, index] of queries) {
    const minute = time % (2 * n);
    if (minute < n) {
      const position = minute + index;
      answer.push(position < n ? nums[position] : -1);
    } else {
      const length = minute - n;
      answer.push(index < length ? nums[index] : -1);
    }
  }
  return answer;
}

