function elementInNums(nums, queries) {
  // Simulate the array minute by minute and read each query off when its minute comes.
  const order = queries.map((_, j) => j).sort((a, b) => queries[a][0] - queries[b][0]);
  const result = new Array(queries.length).fill(-1);
  let current = nums.slice();
  let shrinking = true;
  let minute = 0;
  for (const j of order) {
    const [time, index] = queries[j];
    while (minute < time) {
      if (shrinking) {
        current.shift();
        if (current.length === 0) shrinking = false;
      } else {
        current.push(nums[current.length]);
        if (current.length === nums.length) shrinking = true;
      }
      minute++;
    }
    result[j] = index < current.length ? current[index] : -1;
  }
  return result;
}

