function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(60, 100);
    const nums = Array.from({ length: n }, () => int(0, 100));
    const queries = Array.from({ length: 2000 }, () => [rand() < 0.2 ? int(99000, 100000) : int(0, 100000), int(0, n - 1)]);
    return [nums, queries];
  }
  const n = int(1, 6);
  const top = rand() < 0.5 ? 9 : 100;
  const nums = Array.from({ length: n }, () => int(0, top));
  const horizon = rand() < 0.8 ? 4 * n + 2 : 60;
  const queries = Array.from({ length: int(1, 10) }, () => [int(0, horizon), int(0, n - 1)]);
  return [nums, queries];
}
